insert into public.learning_cards (lesson_id, position, title, blocks) values ('7cfe97f1-dd32-5a05-93c9-6a9c53f88cd7', 1, 'El Maestro', '[{"type":"keyfigure","value":"5","label":"Titres de Juan Manuel Fangio dans les années 1950"},{"type":"text","text":"L’Argentin gagne avec quatre écuries différentes : Alfa Romeo, Mercedes, Ferrari et Maserati. Une performance unique."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('7cfe97f1-dd32-5a05-93c9-6a9c53f88cd7', 2, 'Le génie écossais', '[{"type":"text","text":"Jim Clark remporte deux titres avec Lotus, en 1963 et 1965. Beaucoup le considèrent comme le pilote le plus naturellement doué de l’histoire."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('7cfe97f1-dd32-5a05-93c9-6a9c53f88cd7', 3, 'Le combat pour la sécurité', '[{"type":"text","text":"Triple champion (1969, 1971, 1973), Jackie Stewart milite pour des circuits plus sûrs, à une époque où les accidents mortels étaient fréquents."}]'::jsonb);
