insert into public.learning_cards (lesson_id, position, title, blocks) values ('f81796ff-4404-5aa1-b879-ffef0d9b7f6b', 1, 'Le Professeur', '[{"type":"text","text":"Calculateur et précis, Alain Prost gagne quatre titres : 1985, 1986 et 1989 avec McLaren, puis 1993 avec Williams. Il reste le seul Français champion du monde de F1."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('f81796ff-4404-5aa1-b879-ffef0d9b7f6b', 2, 'Le magicien', '[{"type":"text","text":"Ayrton Senna est titré en 1988, 1990 et 1991. Roi de la qualification et de la pluie, il gagne six fois à Monaco, un record. Il se tue à Imola le 1er mai 1994."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('f81796ff-4404-5aa1-b879-ffef0d9b7f6b', 3, 'Suzuka', '[{"type":"text","text":"En 1989 puis en 1990, les deux rivaux s’accrochent au Grand Prix du Japon, à Suzuka. Les deux fois, l’accrochage décide du titre."}]'::jsonb);
