insert into public.learning_cards (lesson_id, position, title, blocks) values ('27e21bfe-fd0c-5aec-9fc9-442cd27bf240', 1, 'Les années Schumacher', '[{"type":"text","text":"Michael Schumacher gagne deux titres avec Benetton (1994, 1995), puis cinq de suite avec Ferrari, de 2000 à 2004 : sept au total."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('27e21bfe-fd0c-5aec-9fc9-442cd27bf240', 2, 'Les successeurs', '[{"type":"list","items":["Fernando Alonso : 2005 et 2006 avec Renault.","Sebastian Vettel : quatre titres de suite avec Red Bull, de 2010 à 2013.","Lewis Hamilton : sept titres entre 2008 et 2020, avec McLaren puis Mercedes."]}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('27e21bfe-fd0c-5aec-9fc9-442cd27bf240', 3, 'La nouvelle génération', '[{"type":"text","text":"En 2016, à 18 ans, Max Verstappen devient le plus jeune vainqueur d’un Grand Prix. Il décroche son premier titre en 2021."}]'::jsonb);
