insert into public.learning_cards (lesson_id, position, title, blocks) values ('397c5136-74b5-5535-ad4b-6c058e504ad1', 1, 'Toujours là', '[{"type":"text","text":"Ferrari est la seule écurie à avoir disputé toutes les saisons du championnat du monde depuis 1950."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('397c5136-74b5-5535-ad4b-6c058e504ad1', 2, 'Maranello', '[{"type":"text","text":"Fondée par Enzo Ferrari, la Scuderia est installée à Maranello, en Italie. Ses fans, les tifosi, envahissent la piste de Monza chaque année."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('397c5136-74b5-5535-ad4b-6c058e504ad1', 3, 'Le cheval cabré', '[{"type":"fact","text":"Le cheval cabré ornait l’avion de Francesco Baracca, as de l’aviation italienne pendant la Première Guerre mondiale. Sa famille l’offre à Enzo Ferrari."}]'::jsonb);
