insert into public.learning_cards (lesson_id, position, title, blocks) values ('fe113dca-9731-56a4-a04d-a441467b9839', 2, 'Les grandes heures', '[{"type":"text","text":"McLaren domine la fin des années 1980 avec Prost et Senna. Williams règne au début des années 1990, Prost y décroche son dernier titre en 1993."}]'::jsonb);
