insert into public.learning_cards (lesson_id, position, title, blocks) values ('2f452c68-41b7-5d01-8daf-d9dda2857f7f', 2, '2016, le titre et la retraite', '[{"type":"text","text":"Nico Rosberg bat son coéquipier Lewis Hamilton pour le titre 2016, puis annonce sa retraite cinq jours plus tard."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('2f452c68-41b7-5d01-8daf-d9dda2857f7f', 3, '2021, le dernier tour', '[{"type":"text","text":"Hamilton et Verstappen arrivent à égalité de points au dernier Grand Prix, à Abu Dhabi. Verstappen dépasse Hamilton dans le dernier tour et prend le titre."}]'::jsonb);
